<script setup>


import {computed, ref, watch} from 'vue';

const props=defineProps({comparison:Object,selected:Array,edited:Object,saving:Boolean});
const emit=defineEmits(['update:selected']);
const active=ref(''),onlyChanges=ref(true),selectionError=ref('');
const tree=computed(()=>props.comparison.task.tree),diffs=computed(()=>new Map(props.comparison.differences.map(d=>[d.key,d])));
const nodes=computed(()=>props.comparison.tree_nodes||[]),nodeMap=computed(()=>new Map(nodes.value.map(n=>[n.key,n])));
watch(()=>props.comparison,()=>{active.value=props.comparison.differences[0]?.key||'';selectionError.value='';},{immediate:true});
const current=computed(()=>diffs.value.get(active.value));
const currentNode=computed(()=>nodeMap.value.get(active.value));
const labels={insert:'新增',update:'更新',unchanged:'一致',target_only:'仅目标（保留）'};
function ancestors(key){const out=[],seen=new Set();let n=nodeMap.value.get(key);while(n?.parent_key&&!seen.has(n.parent_key)){seen.add(n.parent_key);out.push(n.parent_key);n=nodeMap.value.get(n.parent_key);}return out;}
const treeRows=computed(()=>{
 const included=new Set();for(const n of nodes.value){if(!onlyChanges.value||diffs.value.has(n.key)){included.add(n.key);for(const p of ancestors(n.key))included.add(p);}}
 const children=new Map();for(const n of nodes.value){const parent=nodeMap.value.has(n.parent_key)?n.parent_key:'';if(!children.has(parent))children.set(parent,[]);children.get(parent).push(n);}
 const out=[],seen=new Set();function walk(parent,depth){for(const n of children.get(parent)||[]){if(seen.has(n.key))continue;seen.add(n.key);if(!included.has(n.key))continue;out.push({...n,level:depth,hasChildren:(children.get(n.key)||[]).some(x=>included.has(x.key))});walk(n.key,depth+1);}}walk('',0);return out;
});
const treeData=computed(()=>{const byKey=new Map(treeRows.value.map(n=>[n.key,{...n,title:n.label,children:[]}])),roots=[];for(const node of byKey.values()){const parent=byKey.get(node.parent_key);if(parent)parent.children.push(node);else roots.push(node)}return roots})
const expandedKeys=ref([]);watch(treeRows,rows=>expandedKeys.value=rows.filter(n=>n.hasChildren).map(n=>n.key),{immediate:true})
function select(key,on){selectionError.value='';const next=new Set(props.selected);if(on){next.add(key);if(tree.value)for(const parent of ancestors(key)){if(diffs.value.get(parent)?.kind==='insert')next.add(parent);}}else{next.delete(key);if(diffs.value.get(key)?.kind==='insert')for(const child of props.selected){if(ancestors(child).includes(key))next.delete(child);}}if(next.size>50){selectionError.value='每份草稿最多 50 行（含依赖父节点），请缩小本次迁移范围。';return;}emit('update:selected',[...next]);}
function selectAll(){selectionError.value='';if(props.comparison.differences.length>50){selectionError.value='差异超过 50 行，请按菜单分支分批选择。';return;}emit('update:selected',props.comparison.differences.map(d=>d.key));}
function locked(col){return props.comparison.task.keys.includes(col)||!!tree.value&&[tree.value.id_field,tree.value.parent_field].includes(col);}
function display(v){return v===null?'NULL':v===undefined?'不存在':v===''?'（空字符串）':v;}
function changes(d){return props.comparison.columns.filter(col=>JSON.stringify(d.before?.[col])!==JSON.stringify(d.after[col])).join('、');}

import {TreeRoot,TreeItem} from 'reka-ui'


import {Button,Checkbox,Empty,EmptyDescription,EmptyHeader,Input,Textarea,Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from '../../shared/shadcn-ui.js'
</script>
<template><section :class="{hierarchy:tree}" class="sync-diff"><div class="diff-tools"><b>{{tree?'树状层级差异':'表格差异'}}</b><Button @click="selectAll" variant="outline" size="default" type="button" :disabled="(saving)">全选差异</Button><Button @click="emit('update:selected',[])" variant="outline" size="default" type="button" :disabled="(saving||!selected.length)">清空选择</Button><span>已选 {{selected.length}} / 50</span><label v-if="tree"><Checkbox v-model="onlyChanges"/> 仅差异及相关父节点</label></div><p v-if="selectionError" role="alert" class="selection-error">{{selectionError}}</p><p v-if="tree" class="hint">按稳定字段匹配菜单；已有菜单保留目标 ID，新增菜单分配目标 ID，父 ID 自动转换。选择子菜单会带上需要新增的父节点。目标查询请按稳定业务字段筛选，避免新增 ID 超出范围。</p><div class="diff-workspace"><div class="diff-navigation"><template v-if="tree"><TreeRoot v-slot="{flattenItems}" :items="treeData" :get-key="node=>node.key||''" :get-children="node=>node.children?.length?node.children:undefined" :model-value="nodeMap.get(active)" v-model:expanded="expandedKeys" :disabled="saving" @update:model-value="node=>active=node?.key||''" aria-label="菜单层级差异" class="space-y-1 p-2"><TreeItem v-for="node in flattenItems" :key="node._id" v-bind="node.bind" v-slot="{isExpanded,handleToggle}" :style="{paddingLeft:(node.level-1)*16+8+'px'}" class="flex min-w-0 cursor-pointer items-center gap-2 rounded-md py-2 pr-2 text-sm outline-none hover:bg-accent focus-visible:ring-2 focus-visible:ring-ring data-selected:bg-accent"><Button v-if="node.hasChildren" variant="ghost" size="icon-xs" :aria-label="isExpanded?'收起分支':'展开分支'" @click.stop="handleToggle">{{isExpanded?'−':'+'}}</Button><span v-else class="w-6"/><Checkbox v-if="diffs.has(node.value.key)" :model-value="selected.includes(node.value.key)" :disabled="saving" :aria-label="'选择 '+node.value.label" @click.stop @update:model-value="value=>select(node.value.key,value)"/><span class="min-w-0 flex-1 truncate" :title="node.value.label+' · '+node.value.key">{{node.value.label}}</span><span class="text-xs text-muted-foreground">{{labels[node.value.kind]}}</span></TreeItem></TreeRoot><p v-if="!treeRows.length" class="hint">没有差异。取消“仅差异”可查看完整菜单层级。</p></template><div v-else class="sync-table-scroll"><Table class="table-fixed" container-label="同步差异列表" :container-tabindex="0"><TableHeader class="sticky top-0 z-10 bg-background"><TableRow><TableHead class="w-12">选择</TableHead><TableHead class="w-16">状态</TableHead><TableHead>匹配键 / 差异字段</TableHead></TableRow></TableHeader><TableBody><TableRow v-for="d in comparison.differences" :key="d.key" :data-state="active===d.key?'selected':undefined"><TableCell class="align-top"><Checkbox :aria-label="'选择 '+d.key" :model-value="selected.includes(d.key)" :disabled="saving" @update:model-value="value=>select(d.key,value)"/></TableCell><TableCell class="align-top"><span :class="d.kind" class="diff-kind">{{labels[d.kind]}}</span></TableCell><TableCell class="min-w-0"><Button @click="active=d.key" :title="d.key" :aria-pressed="active===d.key" class="node-name h-auto w-full min-w-0 justify-start whitespace-normal px-0 text-left" variant="ghost" size="sm" type="button"><span class="line-clamp-2 break-all">{{d.key}}</span></Button><div :title="changes(d)" class="changed-fields text-xs text-muted-foreground">{{changes(d)}}</div></TableCell></TableRow><TableRow v-if="!comparison.differences.length"><TableCell :colspan="3"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div><section aria-label="字段差异" class="diff-detail"><template v-if="current"><div class="detail-heading"><b>{{currentNode?.label||current.key}}</b><span :class="current.kind" class="diff-kind">{{labels[current.kind]}}</span><label><Checkbox :model-value="selected.includes(current.key)" :disabled="saving" @update:model-value="(value=>select(current.key,value))($event)"/> 纳入本次迁移</label></div><p v-if="tree" class="hint">来源 ID {{currentNode?.source_id}} → 目标 ID {{current.after[tree.id_field]}}；ID 与父 ID 已自动映射。</p><div class="sync-table-scroll"><div class="field-table console-table min-w-0 max-w-full"><div class="max-w-full overflow-auto rounded-lg border" :style="{maxHeight:({x:960}).y?({x:960}).y+'px':undefined}"><Table class="table-fixed w-full"><TableHeader><TableRow><TableHead class="w-[22%]">字段</TableHead><TableHead class="w-[38%]">目标当前值</TableHead><TableHead class="w-[40%]">迁移后值（可编辑）</TableHead></TableRow></TableHeader><TableBody><template v-for="(record,rowIndex) in (comparison.columns.map(col=>({col}))||[])" :key="typeof (&quot;col&quot;)==='function'?(&quot;col&quot;)(record):record[&quot;col&quot;]??rowIndex"><TableRow :class="(r=>JSON.stringify(current.before?.[r.col])!==JSON.stringify(current.after[r.col])?'changed':'')(record)"><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:false}"><template v-for="{record:{col}} in [{record,rowIndex}]">{{col}}<small v-if="comparison.task.keys.includes(col)">匹配键</small><small v-else-if="locked(col)">层级映射</small></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:false}"><template v-for="{record:{col}} in [{record,rowIndex}]"><span class="before">{{display(current.before?.[col])}}</span></template></div></TableCell><TableCell class="align-top"><div class="min-w-0 break-words" :class="{truncate:!!(false)}"><template v-for="{record:{col}} in [{record,rowIndex}]"><span v-if="locked(col)">{{display(edited[current.key][col])}}</span><template v-else><Textarea v-if="typeof current.after[col]==='string'&&(current.after[col].length>120||current.after[col].includes('\n'))" v-model="edited[current.key][col]" :disabled="saving||edited[current.key][col]===null" :aria-label="'迁移后 '+col" rows="4"/><Input v-else v-model="edited[current.key][col]" :disabled="saving||edited[current.key][col]===null" v-bind="{&quot;aria-label&quot;:('迁移后 '+col)}"/><label class="null-control"><Checkbox :model-value="edited[current.key][col]===null" :disabled="saving" @update:model-value="(value=>edited[current.key][col]=value?null:'')($event)"/> NULL</label></template></template></div></TableCell></TableRow></template><TableRow v-if="!(comparison.columns.map(col=>({col}))||[]).length"><TableCell :colspan="3"><Empty><EmptyHeader><EmptyDescription>暂无数据</EmptyDescription></EmptyHeader></Empty></TableCell></TableRow></TableBody></Table></div></div></div></template><p v-else class="hint">{{currentNode?.kind==='target_only'?'此菜单仅存在于目标环境，将保留。':currentNode?'此菜单数据一致，无需迁移。':'点击左侧差异，核对目标当前值与迁移后值。'}}</p></section></div></section></template>
<style scoped>.sync-diff{min-width:0}.diff-tools,.detail-heading{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.diff-tools label,.detail-heading label{display:flex;align-items:center;gap:6px;margin-left:auto}.diff-workspace{display:grid;grid-template-columns:minmax(260px,36%) minmax(0,1fr);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden;margin-top:12px;min-height:260px}.diff-navigation{border-right:1px solid var(--border);max-height:550px;overflow:auto;min-width:0}.diff-detail{padding:14px;min-width:0;max-height:550px;overflow:auto}.sync-table-scroll{overflow:auto;max-width:100%}.changed-fields{max-width:180px;overflow:hidden;text-overflow:ellipsis}.field-table .before{color:var(--muted-foreground)}.field-table .changed{background:var(--brand-soft)}.null-control{display:flex;gap:5px;align-items:center;font-size:.75rem;margin-top:5px}.tree-row{display:flex;align-items:center;gap:7px;min-height:42px;padding:4px 10px 4px calc(10px + var(--depth)*18px);min-width:max-content;border-bottom:1px solid var(--border)}.tree-row.active{background:var(--brand-soft)}.tree-row .node-name{max-width:240px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.expander{display:inline-block;width:20px;flex-shrink:0}.checkbox-space{display:inline-block;width:13px}.diff-kind{font-size:.75rem;color:var(--muted-foreground);white-space:nowrap}.diff-kind.insert{color:var(--ok)}.diff-kind.update{color:var(--brand)}.hint{font-size:.875rem;color:var(--muted-foreground);padding:4px 0}.selection-error{color:var(--error)}@media(max-width:900px){.diff-workspace{grid-template-columns:1fr}.diff-navigation{max-height:300px;border-right:0;border-bottom:1px solid var(--border)}.diff-detail{max-height:none}}</style>

<style scoped>.field-table .before{white-space:pre-wrap;overflow-wrap:anywhere}.field-table small{display:block;font-size:.75rem;color:var(--muted-foreground)}.field-table :deep(textarea){resize:vertical;min-height:100px;max-height:320px}.detail-heading>b{overflow-wrap:anywhere;min-width:0}.diff-navigation :deep([data-slot="table-container"]){overflow:visible}</style>

<style scoped>.diff-navigation,.diff-detail{max-height:clamp(280px,45dvh,550px)}</style>
